{menu:[{label:"Contacts",path:"ps-store/contacts"},{label:"Game Reviews",path:"ps-store/game-reviews"},{label:"Delivery & Payment",path:"ps-store/delivery-payment"},{label:"About Us",path:"ps-store/about-us"}],placeholder:"Search",dropdown:{button:"Product Catalog"}},dO={title:"Contact us",customer_support:{title:"Customer Support",numbers:[{ref:"+380443337007",number:"(044) 333 70 07"},{ref:"+380730013050",number:"(073) 001 30 50"},{ref:"+380672902060",number:"(067) 290 20 60"},{ref:"+380990013050",number:"(099) 001 30 50"}],schedule:[{date:"Wekdays:",time:"9:00 AM to 9:00 PM"},{date:"Weekend:",time:"10:00 AM to 8:00 PM"}]},pickup_points:{title:"Pickup points",description:"Pickup points only store the items you ordered.",links:["Kyiv","13 Zdolbunivska St.","25 P. Sahaidachnoho St."]}},mO={title:"Delivery and Payment",payment:{title:"Ways to pay",list:[{title:"Cash on delivery",description:"The goods are paid in cash directly to the courier, who delivers the order in Kyiv and nearby settlements: Brovary, Boryspil, Bucha, Vyshneve, Vyshgorod, Irpin, Chabany, Chayka and others."},{title:"Cash on delivery via Nova Poshta",description:"Payment in cash upon receipt of the goods at a Nova Poshta branch (the cash on delivery fee will be included in the order price)."},{title:"Bank transfer for individuals",description:"We can accept payment to a current account – in this case there is no commission."},{title:"Credit / Debit card (Visa, MasterCard)",description:"You can pay cashlessly using IBAN details or a bank card (key card), cards via a payment terminal (2% commission) or using Visa and Mastercard bank cards, Apple Pay, Google Pay when paying online on the website; with this payment method, the payment system commission is 1.3%."}]},delivery:{title:"Shipping methods",list:[{title:"Store pickup",description:"You can pick up your order in one of our stores."},{title:"Pickup from Nova Poshta",description:"The delivery cost is paid by the recipient, according to the tariffs of «Nova Poshta». Please note that on the 4th day of storage of the parcel at the branch, it will be returned to us. We also want to note that when choosing such delivery, a commission of 2% of the total order value will be taken into account."},{title:"Nova Poshta parcel locker pickup",description:"The delivery cost is paid by the recipient according to Nova Poshta tariffs. Please note that on the 4th day of storage of the parcel at the branch, it will be returned."},{title:"Home delivery via Nova Poshta",description:"Delivery is carried out by Nova Poshta throughout Ukraine. The delivery cost is paid by the recipient according to Nova Poshta tariffs."}]}},gO={title:"About us",list:[{title:"«Up2date» - the next level in electronics and digital technology!",description:["Among the many online platforms selling electronics, “Up2date” has long been known as a reliable online store where customers can purchase high-quality gadgets and electronics. Since starting our journey back in 2005, our company has continued to grow and expand year after year, offering products from trusted manufacturers. Today, 21 years later, we are proud to offer both our loyal and new customers one of the largest selections of gadgets and electronics in the country.","We work to bring modern and cutting-edge technology and accessories from leading global manufacturers to the Ukrainian market. If you want to be the first among your friends to get the latest smartphone, gaming console, or tablet, be sure to check out our online store!"]},{title:"Up2date store features",description:["The website features a wide range of product categories where you can find accessories for iPad and iPhone, as well as e-readers, watches, headphones, audio equipment, photography gear, and much more. We also offer a large section dedicated to gaming consoles that passionate gamers will truly appreciate.","All categories are regularly updated with new models, so you can always purchase the latest gadgets. Registered customers receive special bonuses, making shopping in our store even more rewarding.",{sub_title:"Key advantages of the Up2date store that make customers choose us:",sub_list:["Competitive prices, additional bonuses, and special promotional offers","Warranty on all products (from 6 to 36 months)","High-quality service that makes shopping with us fast and convenient","A wide product range that satisfies even the most demanding customers","Convenient payment methods, including both cash and cashless payments"]},"For your convenience, you can search for products not only by categories but also by manufacturers listed in alphabetical order. If needed, our managers are always ready to provide professional консультации by phone and help you choose the best option based on your needs."]},{title:"Our motto: Not a day without new arrivals!",description:["We are pleased that our customers include not only residents of Ukraine but also customers from neighboring countries. Over 21 years of operation, it is difficult to count the total number of customers we have served, but one thing we can say with confidence: 9 out of 10 new buyers become our regular customers.","Our online store is updated with new products every day, allowing our customers to be among the first to get the latest gadgets and accessories. We value speed and efficiency, so we deliver orders as quickly as possible across the country and even to neighboring countries.","Shop high-quality products at affordable prices on our website! Make your life more comfortable and convenient with electronics from Up2date!"]}]},pO={advantage:{delivery:{title:"Shipping throughout Ukraine",description:"Over 120 cities"},guarantee:{title:"Guarantee",description:"18-month warranty"},installment:{title:"Installment plan",description:"Installments up to 18 months"},payment:{title:"Payment",description:"Multiple ways to pay"}},favourites:{title:"Popular categories in our store"},best_offers:{title:"Best offer",nav:{trending:"Trending",new_arrivals:"New arrivals",discounts:"Discounts"}},last_articles:{title:"Last Articles"}},yO={title:"Subscribe",subtitle:"Keep up with the newest products",form:{placeholder:"Enter your email address",button:"Subscribe"}},_O={top:{title:"A new level in electronics and digital technology!",description_top:"Welcome to Up2Date – the online store every gamer in Ukraine knows! For many years, we’ve been selling products connected to the gaming industry, from consoles of all models to accessories and audio equipment. Our gamer-focused store offers a huge selection of gadgets and products from leading global brands. Here, you’ll always find exactly what you’re looking for, whether for yourself or as a gift. We provide competitive prices and 100% authentic products.",description_bottom:"Our gaming console store has been around for many years and has earned a strong reputation among Ukrainian gamers. We receive direct supplies from leading manufacturers and constantly update our catalogs. Today, you’ll find not only gaming-related products but also complementary devices and a variety of gadgets from popular brands. Nevertheless, we remain a dedicated gaming tech store and are among the first to bring the latest products to Ukraine."},bottom:{title:"All types of gaming products at Up2Date",description_top:"In our electronics online store, you’ll find everything you need. We constantly update our catalogs and bring in the hottest new arrivals. We also haven’t forgotten about fans of classics and even retro – that’s why our catalogs include retro games, board games, retro consoles, and more. At Up2Date, you can shop the following product categories:",description_list:["Gaming consoles;","Portable gaming consoles;","Console controllers;","Bundles (console + games);","Video games (discs, cartridges & digital codes);","VR gaming devices (PlayStation VR);","Various accessories (cases, cables, screen protectors, memory cards, etc.);","Board games;","Collector’s editions, figures, and more."],description_bottom:["We supply only original products from leading manufacturers such as Sony, Nintendo, Microsoft, Hori, and others. Every product comes with a warranty card.","You can also purchase subscriptions to gaming services on the Up2Date website, including Steam, EA Pass, PlayStation Plus, Xbox Game Pass, and more. Vouchers for these subscriptions can be used personally or purchased as a gift for a gamer friend — it’s a present no one will refuse!","In addition to gaming-related products, we also offer other types of tech, such as electric transport, graphic tablets, crypto wallets, quadcopters, 3D pens, and various accessories. All of this can be purchased on Up2Date in just a few clicks."]}},vO={navigation:{about:"About",specs:"Parameters",description:"Description"},product_code:"Code",stock:{true:"In Stock",false:"Out of Stock"},parameters:"Parameters",description:"Description",buy_button:{add:"Buy",added:"In Cart"}},bO={nav:[{id:"information",title:"Information",links:["Shipping & Payment","About Us"]},{id:"support",title:"Support",links:["Contacts","Returns","Sitemap"]},{id:"additional",title:"Additional",links:["Brands","Gift Cards","Affiliate Program","Promotions"]},{id:"account",title:"Account",links:["Account","Order History","Wishlist","Newsletter"]}],contacts:{addresses:{title:"Addresses:",links:["Kyiv","13 Zdolbunivska St.","25 P. Sahaidachnoho St."]},opening_hours:{title:"Opening hours",links:[{title:"Wekdays:",hours:"9:00 AM to 9:00 PM"},{title:"Weekend:",hours:"10:00 AM to 8:00 PM"}]}}},EO={header:hO,contacts:dO,delivery_payment:mO,about:gO,main:pO,subscription:yO,benefits:_O,product_card:vO,footer:bO},SO={menu:[{label:"Контакти",path:"ps-store/contacts"},{label:"Огляди ігор",path:"ps-store/game-reviews"},{label:"Доставка та оплата",path:"ps-store/delivery-payment"},{label:"Про нас",path:"ps-store/about-us"}],placeholder:"Пошук",dropdown:{button:"Каталог товарів"}},CO={title:"Зв’язатися з нами",customer_support:{title:"Call-центр інтернет-магазину",numbers:[{ref:"+380443337007",number:"(044) 333 70 07"},{ref:"+380730013050",number:"(073) 001 30 50"},{ref:"+380672902060",number:"(067) 290 20 60"},{ref:"+380990013050",number:"(099) 001 30 50"}],schedule:[{date:"Будні дні:",time:"9 до 20"},{date:"Субота - Неділя:",time:"10 до 19"}]},pickup_points:{title:"Пункти видачі",description:"У пунктах видачі представлені лише товари, які ви замовили.",links:["м. Київ","вул. П. Сагайдачного, 25 (тимчасово не працює)","вул. Здолбунівська, 13"]}},TO={title:"Доставка та оплата",payment:{title:"Способи оплати",list:[{title:"Готівкою при отриманні",description:"Готівкою товар оплачується безпосередньо кур'єру, який доставляє замовлення по Києву та прилеглих населених пунктах: Бровари, Бориспіль, Буча, Вишневе, Вишгород, Ірпінь, Чабани, Чайка та інші."},{title:"Накладений платіж",description:"Оплата готівкою після отримання товару у відділенні Нової пошти (у вартість замовлення буде включена комісія післяплати)."},{title:"На рахунок для Фіз. осіб",description:"Ми можемо прийняти оплату на розрахунковий рахунок – в цьому випадку комісіі немає."},{title:"Картою Visa/MasterCard",description:"Безготівковим способом можна сплатити по реквізитам IBAN, або банківської карти (ключ-карти), картками через платіжний термінал (комісія 2%) або за допомогою банківських карт Visa та Mastercard, Apple Pay, Google Pay при оплаті онлайн на сайті, при такому способі оплати комісія платіжної системи становить 1.3%."}]},delivery:{title:"Способи доставки",list:[{title:"Самовивіз з магазину",description:"Замовлення можна самостійно отримати в одному з наших магазинів."},{title:"Самовивіз з Нової пошти",description:"Вартість доставлення сплачується отримувачем, згідно з тарифами «Нової пошти». Зверніть увагу, що на 4й день зберігання посилки у відділенні, вона буде повернута до нас. Також хочемо зазначити, що при виборі такого доставлення буде врахована комісія у розмірі 2% від повної вартості замовлення."},{title:"Самовивіз з поштомату Нова пошта",description:"Вартість доставкі сплачується отримувачем згідно з тарифів Нової пошти. Зверніть увагу, що на 4й день зберігання посилки у відділенні, вона буде повернута."},{title:"Адресна доставка Нова пошта",description:"Доставка здійснюється службою Нова пошта по всій Україні. Вартість доставкі сплачується отримувачем згідно з тарифів Нової пошти."}]}},wO={title:"Про нас",list:[{title:"«Up2date» - новий рівень у світі електроніки та цифрової техніки!",description:["Серед великої кількості різноманітних інтернет-майданчиків з продажу техніки <<Up2date>> вже давно відомий як надійний онлайн-магазин, де можна придбати якісні гаджети та електроніку. Розпочавши свою роботу в далекому 2005 року, наша компанія з кожним новим роком розвивалася і розширювалася, пропонуючи своїм клієнтам товари перевірених виробників. Сьогодні, через 21 років, ми раді запропонувати своїм постійним та новим покупцям найбільший вибір гаджетів та електроніки в країні!","Ми працюємо для того, щоб постачати на ринок України сучасну та <<мегакруту>> техніку та аксесуари від провідних світових виробників. Якщо ви хочете першим серед своїх знайомих придбати останню модель смартфона, ігрову приставку або планшет, тоді вам неодмінно варто заглянути до нашого онлайн-магазину!"]},{title:"Особливості інтернет-магазину <<Up2date>>.",description:["На сайті представлено безліч категорій товарів, де ви можете вибрати як аксесуари до iPad, iPhone, так і електронні книги, годинники, навушники, аудіо та фототехніку та багато іншого. Також у нас є великий розділ по ігрових приставках, що гідно оцінять затяті геймери.","Усі категорії постійно поповнюються новими моделями, тож ви завжди зможете придбати сучасний гаджет. Усім своїм клієнтам, які реєструвалися в онлайн-магазині, ми надаємо приємні бонуси на покупки, що дозволяє вигідно замовляти товари.",{sub_title:"Головні переваги магазину «Up2date», завдяки яким нас обирають:",sub_list:["Низькі ціни, додаткові бонуси та акційні пропозиції","Надання гарантій на весь товар (від 6 до 36 місяців)","Якісний сервіс, що дозволяє здійснювати у нас покупки вигідно та швидко","Широкий асортимент, який задовольнить смаки навіть найвибагливіших клієнтів","Доступні способи оплати: як готівковим, так і безготівковим способом"]},"Для зручності користування інтернет-магазином ви можете здійснювати пошук товару не тільки за категоріями, а й за виробниками, які вказані в алфавітному порядку. При необхідності наші менеджери в телефонному режимі завжди готові надати грамотні консультації щодо вибору товару та порекомендують найкращий варіант, виходячи з ваших запитів."]},{title:"Наш девіз: жодного дня без новинок!",description:["Нам приємно, що наші покупці – це не лише жителі України, а й жителі близького зарубіжжя. За 21 років роботи важко підрахувати кількість усіх наших клієнтів, але одне ми з упевненістю можемо сказати: 9 із 10 наших нових покупців стають нашими постійними клієнтами.","Щодня онлайн-магазин поповнюється новим товаром, щоб наші клієнти серед перших могли придбати той чи інший гаджет або аксесуар. Ми цінуємо оперативність, тому доставляємо товар у максимально стислий термін у будь-який куточок країни і навіть країни ближнього зарубіжжя.","Замовляйте якісний товар за доступними цінами на нашому сайті! Зробіть своє життя більш комфортним та зручним за допомогою електроніки від магазину «Up2date»!"]}]},AO={advantage:{delivery:{title:"Доставка по всій Україні",description:"Понад 120 міст"},guarantee:{title:"Гарантія",description:"Гарантія 18 місяців"},installment:{title:"Розстрочка",description:"Розстрочка до 18 місяців"},payment:{title:"Оплата",description:"Великий вибір варіантів оплати"}},favourites:{title:"Популярні категорії нашого магазину"},best_offers:{title:"Краща пропозиція",nav:{trending:"Популярні",new_arrivals:"Новинки",discounts:"Знижки"}},last_articles:{title:"Останні статті"}},xO={title:"Підпишись",subtitle:"І будь в курсі останніх новинок",form:{placeholder:"Введіть адресу електронної пошти",button:"Підписатись"}},RO={top:{title:"Новий рівень у світі електроніки та цифрової техніки!",description_top:"Ласкаво просимо до Up2Date – інтернет-магазин, знайомий кожному геймеру в Україні! Вже багато років ми займаємося продажем товарів, так чи інакше пов'язаних з ігровою індустрією, від ігрових приставок всіх моделей до аксесуарів та аудіотехніки. Наш магазин для геймерів реалізує величезну кількість гаджетів та товарів від провідних світових виробників. Тут ви завжди знайдете те, що шукаєте для себе чи на подарунок. Ми пропонуємо вигідні ціни та 100% оригінальну продукцію.",description_bottom:"Наш магазин ігрових приставок відкрився багато років тому і заслужив на високий авторитет серед українських геймерів. Ми отримуємо прямі поставки від провідних виробників та постійно оновлюємо наші каталоги. Сьогодні в них можна знайти не тільки товари, пов'язані з ігровою індустрією, а й супутні девайси та різні гаджети популярних брендів. Тим не менш, ми залишаємося магазином ігрової техніки та одними з перших завозимо до України."},bottom:{title:"Всі види товарів для геймерів в інтернет-магазині Up2Date",description_top:"У нашому інтернет-магазині електроніки ви знайдете те, що вам потрібно. Ми постійно оновлюємо наші каталоги та привозимо найгарячіші новинки. Також ми не забуваємо і про любителів класики і навіть ретро – тому в наших каталогах присутні також ретро-ігри, настільні ігри, ретро-консолі та ін. Так, у Up2Date ви можете придбати наступні категорії товарів:",description_list:["Ігрові консолі;","Портативні ігрові приставки;","Контролери для приставок;","Бандли (приставки з іграми);","Відеоігри на фізичних носіях (дисках та картриджах) та у вигляді ваучерів (ключів) на скачування;","Девайси для ігор у віртуальній реальності (PlayStation VR);","Різноманітні аксесуари (чохли, кейси, кабелі, захисне скло, карти пам'яті та ін.);","Настільні ігри;","Колекційні видання та фігурки, та багато іншого."],description_bottom:["Ми постачаємо лише оригінальні товари від провідних виробників: Sony, Nintendo, Microsoft, Hori та інших. Кожен виріб супроводжується гарантійним талоном.","Також на сайті Up2Date ви можете придбати підписки на ігрові сервіси: Steam, EA Pass, PlayStation Plus, Game Pass для Xbox, і т.д. Ваучери на ці підписки можна використати самостійно або купити на подарунок другові-геймеру – від такого презенту точно не відмовиться ніхто!","Крім товарів, безпосередньо пов'язаних з геймінгом, ми також пропонуємо інші види техніки, такі як електротранспорт, графічні планшети, криптогаманці, квадрокоптери, 3D-ручки та інші аксесуари. Все це ви можете придбати на Up2Date буквально на кілька кліків."]}},NO={navigation:{about:"Про товар",specs:"Характеристики",description:"Опис"},product_code:"Код",stock:{true:"В наявності",false:"Немає в наявності"},parameters:"Характеристики",description:"Опис",buy_button:{add:"Купити",added:"В кошику"}},DO={nav:[{id:"information",title:"Інформація",links:["Доставка та оплата","Про нас"]},{id:"support",title:"Служба підтримки",links:["Контакти","Повернення товару","Карта сайту"]},{id:"additional",title:"Додатково",links:["Виробники","Подарункові сертифікати","Партнерська програма","Акції"]},{id:"account",title:"Особистий кабінет",links:["Особистий кабінет","Історія замовлень","Закладки","Розсилка"]}],contacts:{addresses:{title:"Адреса:",links:["м.Київ","вул. Здолбунівська, 13","вул. П. Сагайдачного, 25"]},opening_hours:{title:"Графік роботи",links:[{title:"Будні дні:",hours:"з 9 до 21 години"},{title:"Субота-неділя:",hours:"з 10 до 20 години"}]}}},OO={header:SO,contacts:CO,delivery_payment:TO,about:wO,main:AO,subscription:xO,benefits:RO,product_card:NO,footer:DO};Ye.use(E5).use(VE).init({resources:{[da.EN]:{translation:EO},[da.UK]:{translation:OO}},fallbackLng:"en",detection:{order:["localStorage","navigator"],caches:["localStorage"],checkWhitelist:!0},whitelist:["en","uk"],interpolation:{escapeValue:!1}});const Uv=localStorage.getItem("i18nextLng");Uv&&!["en","uk"].includes(Uv)&&(localStorage.setItem("i18nextLng","en"),Ye.changeLanguage(da.EN));const IO=CR({reducer:{products:KR,product:KD,cart:nD,favorites:hD}});lb.createRoot(document.getElementById("root")).render(b.jsx(U.StrictMode,{children:b.jsx(I6,{children:b.jsx(Tw,{store:IO,children:b.jsx(XD,{})})})}));
